nodos = {
    "ana": {"tipo": "Persona", "edad": 30},
    "luis": {"tipo": "Persona", "edad": 28},
    "sol": {"tipo": "Persona", "edad": 35},
}
aristas = [
    ("ana", "AMIGO_DE", "luis"),
    ("luis", "AMIGO_DE", "sol"),
]

def amigos_directos(persona):
    return [b for a, rel, b in aristas if a == persona and rel == "AMIGO_DE"]

def amigos_de_amigos(persona):
    resultado = set()
    for amigo in amigos_directos(persona):
        for candidato in amigos_directos(amigo):
            if candidato != persona:
                resultado.add(candidato)
    return sorted(resultado)

print(f"Amigos directos de ana: {amigos_directos('ana')}")
print(f"Amigos de amigos de ana: {amigos_de_amigos('ana')}")
print(f"Nodos totales: {len(nodos)}, aristas totales: {len(aristas)}")
